current.custom_css:
.m-topbar a[href*="pinterest"],
.m-topbar a[href*="twitter"], .m-topbar a[href*="snapchat"], .m-topbar a[href*="youtube"],.m-topbar a[href*="tiktok"]  {
	display: none;
}
.m-color-{
  font-size: 12px;
  font-weight: 500;
  text-transform: capitalize;
  padding: 4px 10px;
  border-radius: 40px;
  background: #000;
}
.m-icon-box--small {
  border-top: 1px solid rgb(var(--color-border));
}
.m-icon-box--small .m-icon-box__heading {
  line-height: 26px;
  font-size: 18px;
  margin-bottom: 6px;
}
body .m-footer--block .social-media-links {
  gap: 12px;
  margin: 0;
  padding: 5px 0;
}
body .m-footer--block .social-media-links a {
  color: #222;
  width: 48px;
  height: 48px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background-color: #E9E9E9;
  transition: all .3s;
}
body .m-footer--block .social-media-links a:hover {
  background-color: #222;
  color: #fff;
  box-shadow: 0 0 0 0.2rem #222;
}

/* Collage Tabs: hide tab navigation */
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tabs__header,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tabs__nav,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tab-nav,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__header,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__nav,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt [role="tablist"],
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt [data-tab-nav] {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  overflow: hidden !important;
}

/* Remove active-tab underline and preserve label styling */
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt [role="tab"],
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tab-nav__item,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tabs__nav-item {
  border-bottom: 0 !important;
  box-shadow: none !important;
  text-transform: uppercase !important;
  font-size: 14px !important;
  font-weight: 700 !important;
  letter-spacing: 0.12em !important;
}
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt [role="tab"]::before,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt [role="tab"]::after,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tab-nav__item::before,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tab-nav__item::after,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tabs__nav-item::before,
#shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-tabs__nav-item::after {
  display: none !important;
  border: 0 !important;
}

/* Collage Tabs: mobile edge-to-edge hero-style layout */
@media screen and (max-width: 749px) {
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt &gt; * {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
  }
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__item,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__image,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__image-wrap,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__media,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__content,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__content-wrap {
    width: 100% !important;
    max-width: 100% !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    gap: 0 !important;
  }
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__image img,
  #shopify-section-template--19971646947479__collage_tabs_Rqt9Pt .m-collage-tabs__media img {
    display: block !important;
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
  }
}
